//! `clamp`: restrict a value to a closed range.

/// Return `x` limited to the closed range `[lo, hi]`:
/// `lo` if `x < lo`, `hi` if `x > hi`, otherwise `x`.
///
/// # Precondition
///
/// `lo <= hi`. Behavior when `lo > hi` is unspecified by this contract.
pub fn clamp(x: i64, lo: i64, hi: i64) -> i64 {
    if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
}

#[cfg(test)]
mod tests {
    use super::clamp;
    use proptest::prelude::*;

    #[test]
    fn basic_below() {
        assert_eq!(clamp(-5, 0, 10), 0);
        assert_eq!(clamp(i64::MIN, i64::MIN, 0), i64::MIN);
        assert_eq!(clamp(-100, i64::MIN, i64::MAX), -100);
    }

    #[test]
    fn basic_inside() {
        assert_eq!(clamp(5, 0, 10), 5);
        assert_eq!(clamp(0, 0, 10), 0);
        assert_eq!(clamp(10, 0, 10), 10);
        assert_eq!(clamp(0, 0, 0), 0);
    }

    #[test]
    fn basic_above() {
        assert_eq!(clamp(15, 0, 10), 10);
        assert_eq!(clamp(i64::MAX, 0, i64::MAX), i64::MAX);
    }

    #[test]
    fn extremes() {
        assert_eq!(clamp(i64::MIN, i64::MIN, i64::MAX), i64::MIN);
        assert_eq!(clamp(i64::MAX, i64::MIN, i64::MAX), i64::MAX);
        assert_eq!(clamp(i64::MIN, -1, i64::MAX), -1);
        assert_eq!(clamp(i64::MAX, i64::MIN, 1), 1);
        assert_eq!(clamp(i64::MAX, i64::MIN, i64::MIN), i64::MIN);
        assert_eq!(clamp(i64::MIN, i64::MAX, i64::MAX), i64::MAX);
    }

    /// A random `(lo, hi)` pair with `lo <= hi` built without any
    /// overflowing/underflowing arithmetic (safe in debug builds).
    fn rand_range(lo: i64, span: u64) -> (i64, i64) {
        // Cap span at i64::MAX *before* casting: `u64 as i64` is a
        // bit-preserving cast, so values above i64::MAX would become
        // negative. After the cap the cast is exact and non-negative.
        let d = span.min(i64::MAX as u64) as i64;
        // d >= 0, so saturating_add can only clamp to i64::MAX, which is
        // still >= lo. Hence hi >= lo always, and nothing panics.
        let hi = lo.saturating_add(d);
        (lo, hi)
    }

    proptest! {
        #[test]
        fn in_range_is_identity(x in any::<i64>()) {
            // If x itself is the bound, clamping must be the identity.
            prop_assert_eq!(clamp(x, x, x), x);
        }

        #[test]
        fn result_always_in_bounds(x in any::<i64>(), lo in any::<i64>(), span in any::<u64>()) {
            let (lo, hi) = rand_range(lo, span);
            prop_assert!(lo <= hi);
            let c = clamp(x, lo, hi);
            prop_assert!((c >= lo) && (c <= hi), "clamp({},{},{})={} out of bounds", x, lo, hi, c);
        }

        #[test]
        fn sentinel_xs_respect_bounds(lo in any::<i64>(), span in any::<u64>()) {
            let (lo, hi) = rand_range(lo, span);
            // Sentinels built with wrapping arithmetic: just i64s to feed as x.
            let xs = [
                i64::MIN, i64::MAX,
                i64::MIN / 2, i64::MAX / 2,
                lo.wrapping_sub(1), lo, hi, hi.wrapping_add(1),
                lo.wrapping_add(hi).wrapping_div(2),
                lo.wrapping_add(hi / 2),
            ];
            for x in xs {
                let c = clamp(x, lo, hi);
                prop_assert!((c >= lo) && (c <= hi));
            }
        }

        #[test]
        fn matches_reference_and_std(x in any::<i64>(), lo in any::<i64>(), span in any::<u64>()) {
            let (lo, hi) = rand_range(lo, span);

            let expected = if x < lo { lo } else if x > hi { hi } else { x };
            prop_assert_eq!(clamp(x, lo, hi), expected);
            // Also agrees with std's own clamp, the canonical definition.
            prop_assert_eq!(clamp(x, lo, hi), x.clamp(lo, hi));
        }
    }
}

//! Computes the midpoint of two `i64` values, rounding toward negative infinity.

/// Returns `floor((a + b) / 2)`, computed exactly.
///
/// The exact sum `a + b` may not fit in an `i64`, so the addition is
/// performed in an `i128`. The result always fits in an `i64` because
/// `i64::MIN <= floor((a + b) / 2) <= i64::MAX` for all `i64` inputs.
pub fn midpoint(a: i64, b: i64) -> i64 {
    // Exact sum; fits in i128 since |a + b| <= 2^64 - 2.
    let s: i128 = a as i128 + b as i128;
    // Truncated division: for odd negative s this is the ceiling,
    // so step down by one to get the floor.
    let m = s / 2;
    let m = if s < 0 && (s & 1) != 0 { m - 1 } else { m };
    // m is within [i64::MIN as i128, i64::MAX as i128].
    m as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// Exact reference using i128 arithmetic.
    fn ref_midpoint(a: i64, b: i64) -> i64 {
        let s: i128 = a as i128 + b as i128;
        // floor(s / 2) for i128 s
        let v = if s >= 0 { s / 2 } else { (s - 1) / 2 };
        v as i64
    }

    #[test]
    fn basic_cases() {
        assert_eq!(midpoint(0, 0), 0);
        assert_eq!(midpoint(1, 1), 1);
        assert_eq!(midpoint(1, 2), 1); // floor(1.5)
        assert_eq!(midpoint(2, 2), 2);
        assert_eq!(midpoint(3, 3), 3);
        assert_eq!(midpoint(0, 1), 0); // floor(0.5)
        assert_eq!(midpoint(-1, 2), 0); // floor(0.5)
        assert_eq!(midpoint(-3, 2), -1); // floor(-0.5)
        assert_eq!(midpoint(3, -2), 0); // floor(0.5)
        assert_eq!(midpoint(-1, -1), -1);
        assert_eq!(midpoint(-3, -3), -3);
        assert_eq!(midpoint(-3, -4), -4); // floor(-3.5)
        assert_eq!(midpoint(-3, -2), -3); // floor(-2.5)
        assert_eq!(midpoint(1, -1), 0);
        assert_eq!(midpoint(2, -3), -1); // floor(-0.5)
        assert_eq!(midpoint(-2, 3), 0); // floor(0.5)
    }

    #[test]
    fn extremes() {
        assert_eq!(midpoint(i64::MIN, i64::MIN), i64::MIN);
        assert_eq!(midpoint(i64::MAX, i64::MAX), i64::MAX);
        assert_eq!(midpoint(i64::MIN, i64::MAX), -1); // floor(-0.5)
        assert_eq!(midpoint(i64::MAX, i64::MIN), -1);
        assert_eq!(midpoint(i64::MIN + 1, i64::MIN + 1), i64::MIN + 1);
        assert_eq!(midpoint(i64::MAX - 1, i64::MAX - 1), i64::MAX - 1);
        assert_eq!(midpoint(i64::MIN, i64::MIN + 1), i64::MIN);
        assert_eq!(midpoint(i64::MAX, i64::MAX - 1), i64::MAX - 1);
        assert_eq!(midpoint(i64::MIN, 0), i64::MIN / 2); // exact, even sum
        assert_eq!(midpoint(i64::MAX, 0), i64::MAX / 2); // floor(2^62 - 0.5)
        assert_eq!(midpoint(i64::MIN, 1), i64::MIN / 2); // floor((MIN+1)/2)
        assert_eq!(midpoint(i64::MAX, -1), i64::MAX / 2); // floor((MAX-1)/2)
    }

    proptest! {
        #[test]
        fn prop_matches_exact_reference(a: i64, b: i64) {
            assert_eq!(midpoint(a, b), ref_midpoint(a, b));
        }

        #[test]
        fn prop_symmetric(a: i64, b: i64) {
            assert_eq!(midpoint(a, b), midpoint(b, a));
        }

        #[test]
        fn prop_idempotent(a: i64) {
            assert_eq!(midpoint(a, a), a);
        }

        #[test]
        fn prop_between_operands(a: i64, b: i64) {
            let m = midpoint(a, b);
            assert!(m >= a.min(b) && m <= a.max(b));
        }

        // The result m must satisfy a + b == 2m or 2m + 1 (checked exactly
        // in i128), i.e. m is the floor of the mean.
        #[test]
        fn prop_is_floor_of_mean(a: i64, b: i64) {
            let m = midpoint(a, b) as i128;
            let s = a as i128 + b as i128;
            let rem = s - 2 * m;
            prop_assert!((rem == 0 || rem == 1) && m <= (s + 1) / 2);
        }

        #[test]
        fn prop_shift(a: i64, b: i64) {
            // midpoint(a + 2, b + 2) == midpoint(a, b) + 2 when no i64 overflow.
            if let (Some(a2), Some(b2)) = (a.checked_add(2), b.checked_add(2)) {
                if let Some(m2) = midpoint(a, b).checked_add(2) {
                    assert_eq!(midpoint(a2, b2), m2);
                }
            }
        }
    }
}

//! Saturating sum over a slice of `i64` values.

/// Add the elements of `a` from left to right, starting from 0,
/// where every single addition saturates: if the exact running total
/// would exceed `i64::MAX` it becomes `i64::MAX`, if it would fall
/// below `i64::MIN` it becomes `i64::MIN`.
///
/// Returns the final running total.
pub fn sat_sum(a: &[i64]) -> i64 {
    a.iter().fold(0_i64, |acc, &x| acc.saturating_add(x))
}

#[cfg(test)]
mod tests {
    use super::sat_sum;
    use proptest::prelude::*;

    #[test]
    fn empty_slice_is_zero() {
        assert_eq!(sat_sum(&[]), 0);
    }

    #[test]
    fn ordinary_sums() {
        assert_eq!(sat_sum(&[1, 2, 3]), 6);
        assert_eq!(sat_sum(&[5, -5, 5, -5]), 0);
        assert_eq!(sat_sum(&[-7, -8]), -15);
        assert_eq!(sat_sum(&[42]), 42);
    }

    #[test]
    fn saturates_at_max() {
        assert_eq!(sat_sum(&[i64::MAX]), i64::MAX);
        assert_eq!(sat_sum(&[i64::MAX, 1]), i64::MAX);
        assert_eq!(sat_sum(&[i64::MAX, i64::MAX]), i64::MAX);
        // Once saturated at MAX it stays there while adding positives.
        assert_eq!(sat_sum(&[i64::MAX, i64::MAX, i64::MAX]), i64::MAX);
        // A negative value after saturation moves down from MAX exactly.
        assert_eq!(sat_sum(&[i64::MAX, 1, -1]), i64::MAX - 1);
    }

    #[test]
    fn saturates_at_min() {
        assert_eq!(sat_sum(&[i64::MIN]), i64::MIN);
        assert_eq!(sat_sum(&[i64::MIN, -1]), i64::MIN);
        assert_eq!(sat_sum(&[i64::MIN, i64::MIN]), i64::MIN);
        assert_eq!(sat_sum(&[i64::MIN, i64::MIN, i64::MIN]), i64::MIN);
        // A positive value after saturation moves up from MIN exactly.
        assert_eq!(sat_sum(&[i64::MIN, -1, 1]), i64::MIN + 1);
    }

    #[test]
    fn exact_boundaries() {
        // h = 2^62.
        let h = 1_i64 << 62;
        // 2^62 + 2^62 = 2^63, one past MAX -> saturates.
        assert_eq!(sat_sum(&[h, h]), i64::MAX);
        // (2^62 - 1) + (2^62 - 1) = 2^63 - 2, fits exactly.
        assert_eq!(sat_sum(&[h - 1, h - 1]), i64::MAX - 1);
        // -2^62 + -2^62 = -2^63 = MIN exactly.
        assert_eq!(sat_sum(&[-h, -h]), i64::MIN);
        // -2^62 + (2^62 - 1) = -1, fits exactly.
        assert_eq!(sat_sum(&[-h, h - 1]), -1);
    }

    #[test]
    fn mixed_overshoot_then_recovery() {
        // 0+MAX=MAX; MAX+MAX->MAX (saturated); MAX+MIN = -1 exactly.
        assert_eq!(sat_sum(&[i64::MAX, i64::MAX, i64::MIN]), -1);
        // 0+MIN=MIN; MIN+MIN->MIN (saturated); MIN+MAX = -1 exactly.
        assert_eq!(sat_sum(&[i64::MIN, i64::MIN, i64::MAX]), -1);
        // Recovery then re-saturation on the other side.
        assert_eq!(
            sat_sum(&[i64::MIN, i64::MIN, i64::MAX, i64::MAX, i64::MAX]),
            i64::MAX
        );
    }

    /// Reference implementation: simulate per-step saturation with an
    /// unbounded (i128) accumulator, clamping after every addition.
    fn ref_sat_sum(a: &[i64]) -> i64 {
        let (lo, hi) = (i64::MIN as i128, i64::MAX as i128);
        let mut total: i128 = 0;
        for &x in a {
            // |total| <= hi and |x| <= hi, so the i128 sum never overflows.
            total = (total + x as i128).clamp(lo, hi);
        }
        total as i64
    }

    /// Strategy producing only values at/around the i64 boundaries.
    fn extreme_value() -> impl Strategy<Value = i64> {
        any::<u8>().prop_map(|i| match i {
            0 => i64::MIN,
            1 => i64::MAX,
            2 => i64::MAX - 1,
            3 => i64::MIN + 1,
            _ => 0,
        })
    }

    #[test]
    fn matches_exact_i128_reference() {
        proptest!(
            ProptestConfig::with_cases(512),
            |(a in prop::collection::vec(any::<i64>(), 0..8))| {
                prop_assert_eq!(sat_sum(&a), ref_sat_sum(&a));
            }
        );
    }

    #[test]
    fn small_slices_equal_plain_sum() {
        proptest!(
            ProptestConfig::with_cases(512),
            |(a in prop::collection::vec(-1_000_000i64..=1_000_000, 0..16))| {
                let plain: i64 = a.iter().sum();
                prop_assert_eq!(sat_sum(&a), plain);
            }
        );
    }

    #[test]
    fn extremes_only() {
        proptest!(
            ProptestConfig::with_cases(512),
            |(a in prop::collection::vec(extreme_value(), 0..12))| {
                prop_assert_eq!(sat_sum(&a), ref_sat_sum(&a));
            }
        );
    }

    #[test]
    fn long_random_slices_stay_consistent() {
        proptest!(
            ProptestConfig::with_cases(256),
            |(a in prop::collection::vec(any::<i64>(), 0..1000))| {
                prop_assert_eq!(sat_sum(&a), ref_sat_sum(&a));
            }
        );
    }
}

/// Return how many elements `x` of `a` satisfy `lo <= x <= hi` (inclusive).
/// If `lo > hi` the answer is 0.
pub fn count_in_range(a: &[i64], lo: i64, hi: i64) -> usize {
    if lo > hi {
        return 0;
    }
    a.iter().filter(|&&x| lo <= x && x <= hi).count()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Independent reference: sort and use binary search (partition_point).
    fn reference(a: &[i64], lo: i64, hi: i64) -> usize {
        if lo > hi {
            return 0;
        }
        let mut b = a.to_vec();
        b.sort_unstable();
        let lo_pos = b.partition_point(|&x| x < lo);
        let hi_pos = b.partition_point(|&x| x <= hi);
        hi_pos - lo_pos
    }

    #[test]
    fn empty_slice() {
        assert_eq!(count_in_range(&[], 0, 10), 0);
        assert_eq!(count_in_range(&[], i64::MIN, i64::MAX), 0);
    }

    #[test]
    fn basics() {
        let a = vec![1, 2, 3, 4, 5];
        assert_eq!(count_in_range(&a, 2, 4), 3);
        assert_eq!(count_in_range(&a, 1, 5), 5);
        assert_eq!(count_in_range(&a, 1, 1), 1);
        assert_eq!(count_in_range(&a, 5, 5), 1);
        assert_eq!(count_in_range(&a, 6, 10), 0);
        assert_eq!(count_in_range(&a, -10, 0), 0);
    }

    #[test]
    fn lo_gt_hi_is_zero() {
        let a = vec![1, 2, 3];
        assert_eq!(count_in_range(&a, 5, 2), 0);
        assert_eq!(count_in_range(&a, i64::MAX, i64::MIN), 0);
    }

    #[test]
    fn duplicates() {
        let a = vec![3, 3, 3, 3];
        assert_eq!(count_in_range(&a, 3, 3), 4);
        assert_eq!(count_in_range(&a, 2, 4), 4);
        assert_eq!(count_in_range(&a, 4, 3), 0);
    }

    #[test]
    fn extremes() {
        let a = vec![i64::MIN, 0, i64::MAX];
        assert_eq!(count_in_range(&a, i64::MIN, i64::MAX), 3);
        assert_eq!(count_in_range(&a, i64::MIN, i64::MIN), 1);
        assert_eq!(count_in_range(&a, i64::MAX, i64::MAX), 1);
        assert_eq!(count_in_range(&a, i64::MIN + 1, i64::MAX - 1), 1);
    }

    #[test]
    fn negatives() {
        let a = vec![-5, -3, -1, 0, 1, 3, 5];
        assert_eq!(count_in_range(&a, -5, 5), 7);
        assert_eq!(count_in_range(&a, -3, -1), 2);
        assert_eq!(count_in_range(&a, -1, -3), 0);
    }

    use proptest::prelude::*;

    proptest! {
        #[test]
        fn prop_matches_reference(
            a in prop::collection::vec(any::<i64>(), 0..=200),
            lo in any::<i64>(),
            hi in any::<i64>(),
        ) {
            prop_assert_eq!(count_in_range(&a, lo, hi), reference(&a, lo, hi));
        }

        #[test]
        fn prop_invariants(a in prop::collection::vec(any::<i64>(), 0..=200)) {
            // Full range covers everything.
            prop_assert_eq!(count_in_range(&a, i64::MIN, i64::MAX), a.len());
            // Empty range (lo > hi) is zero.
            prop_assert_eq!(count_in_range(&a, i64::MAX, i64::MIN), 0);
            // Single-point range: count equals multiplicity of that value.
            for &v in &a {
                let expected = a.iter().filter(|&&x| x == v).count();
                prop_assert_eq!(count_in_range(&a, v, v), expected);
            }
            // Monotonicity: widening the range never decreases the count.
            let n = count_in_range(&a, -10, 10);
            prop_assert!(count_in_range(&a, -20, 20) >= n);
            prop_assert!(count_in_range(&a, -10, 20) >= n);
        }
    }
}

/// Returns the smallest index `i` such that `a[i]` is a largest element of `a`.
///
/// `a` is guaranteed to be non-empty. When the maximum value occurs several
/// times, the index of its first occurrence is returned.
pub fn first_max_index(a: &[i64]) -> usize {
    debug_assert!(!a.is_empty(), "first_max_index requires a non-empty slice");
    let mut best = 0;
    for i in 1..a.len() {
        if a[i] > a[best] {
            best = i;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn single_element() {
        assert_eq!(first_max_index(&[42]), 0);
        assert_eq!(first_max_index(&[i64::MIN]), 0);
        assert_eq!(first_max_index(&[i64::MAX]), 0);
    }

    #[test]
    fn unique_maximum() {
        assert_eq!(first_max_index(&[1, 2, 3, 4, 5]), 4);
        assert_eq!(first_max_index(&[5, 4, 3, 2, 1]), 0);
        assert_eq!(first_max_index(&[1, 3, 2, 3, 1, 9, 9]), 5);
    }

    #[test]
    fn repeated_maximum() {
        assert_eq!(first_max_index(&[7, 7, 7]), 0);
        assert_eq!(first_max_index(&[1, 7, 2, 7, 3]), 1);
        assert_eq!(first_max_index(&[7, 1, 7, 2]), 0);
        assert_eq!(first_max_index(&[1, 2, 7, 7, 7, 0]), 2);
        assert_eq!(first_max_index(&[i64::MAX, i64::MAX]), 0);
        assert_eq!(first_max_index(&[i64::MIN, i64::MIN, i64::MIN]), 0);
    }

    #[test]
    fn negatives() {
        assert_eq!(first_max_index(&[-5, -1, -3, -9]), 1);
        assert_eq!(first_max_index(&[-1, -2, -1]), 0);
    }

    #[test]
    fn two_elements() {
        assert_eq!(first_max_index(&[0, 1]), 1);
        assert_eq!(first_max_index(&[1, 0]), 0);
        assert_eq!(first_max_index(&[0, 0]), 0);
    }

    proptest! {
        #[test]
        fn matches_reference(v in prop::collection::vec(any::<i64>(), 1..128)) {
            let expected = v.iter().position(|x| *x == *v.iter().max().unwrap()).unwrap();
            prop_assert_eq!(first_max_index(&v), expected);
        }

        #[test]
        fn returned_index_holds_max_and_is_first(v in prop::collection::vec(any::<i64>(), 1..128)) {
            let i = first_max_index(&v);
            let m = v.iter().max().unwrap();
            prop_assert_eq!(&v[i], m);
            // first occurrence: nothing equal to the max before i
            prop_assert!(v[..i].iter().all(|x| x != m));
        }

        #[test]
        fn result_in_range(v in prop::collection::vec(any::<i64>(), 1..128)) {
            let i = first_max_index(&v);
            prop_assert!(i < v.len());
        }
    }
}

/// Returns the largest index `i` such that `a[i]` is a smallest element of `a`.
///
/// In other words, when the minimum value occurs several times, the index of
/// its last occurrence is returned.
///
/// `a` must be non-empty.
pub fn last_min_index(a: &[i64]) -> usize {
    debug_assert!(!a.is_empty(), "a must be non-empty");

    let mut min = a[0];
    let mut idx = 0;
    // Update on `<=`: whenever the running minimum is repeated, `idx` moves
    // to the later occurrence; when a strictly smaller value appears, it
    // becomes the new minimum. So `idx` is always the last occurrence of the
    // minimum of the prefix scanned so far, and after the full scan that is
    // the last occurrence of the minimum of `a`.
    for (i, &x) in a.iter().enumerate() {
        if x <= min {
            min = x;
            idx = i;
        }
    }
    idx
}

#[cfg(test)]
mod tests {
    use super::last_min_index;
    use proptest::prelude::*;

    #[test]
    fn single_element() {
        assert_eq!(last_min_index(&[42]), 0);
        assert_eq!(last_min_index(&[i64::MIN]), 0);
        assert_eq!(last_min_index(&[i64::MAX]), 0);
    }

    #[test]
    fn unique_minimum_at_various_positions() {
        assert_eq!(last_min_index(&[1, 2, 3, 4, 5]), 0);
        assert_eq!(last_min_index(&[5, 4, 3, 2, 1]), 4);
        assert_eq!(last_min_index(&[5, 1, 3, 2, 4]), 1);
        assert_eq!(last_min_index(&[3, 2, 1, 2, 3]), 2);
    }

    #[test]
    fn repeated_minimum_returns_last_occurrence() {
        assert_eq!(last_min_index(&[2, 1, 2, 1, 3]), 3);
        assert_eq!(last_min_index(&[1, 1, 1, 1]), 3);
        assert_eq!(last_min_index(&[2, 2, 2]), 2);
        assert_eq!(last_min_index(&[5, 5]), 1);
        assert_eq!(last_min_index(&[0, -1, 0, -1, -1, 2]), 4);
    }

    #[test]
    fn all_equal() {
        assert_eq!(last_min_index(&[7, 7, 7, 7, 7, 7]), 5);
        assert_eq!(last_min_index(&[i64::MIN, i64::MIN, i64::MIN]), 2);
    }

    #[test]
    fn negatives_and_extremes() {
        assert_eq!(last_min_index(&[-5, -1, -5, -10, -5]), 3);
        assert_eq!(last_min_index(&[i64::MAX, i64::MIN, i64::MAX]), 1);
        assert_eq!(last_min_index(&[i64::MAX, i64::MAX, i64::MIN, i64::MAX]), 2);
    }

    // Reference used by the property tests: the last index holding the
    // minimum value.
    fn ref_last_min(a: &[i64]) -> usize {
        let min = *a.iter().min().unwrap();
        a.iter().rposition(|&x| x == min).unwrap()
    }

    // Property 1: the returned index holds the minimum value, and it is the
    // *last* occurrence of that minimum (full i64 range, short slices).
    #[test]
    fn prop_last_occurrence_short() {
        proptest! {
            ProptestConfig::with_cases(256),
            |(a in prop::collection::vec(any::<i64>(), 1..=64))| {
                let got = last_min_index(&a);
                let min = *a.iter().min().unwrap();
                prop_assert_eq!(a[got], min);
                prop_assert_eq!(got, ref_last_min(&a));
            }
        }
    }

    // Property 2: on longer slices, same check.
    #[test]
    fn prop_last_occurrence_long() {
        proptest! {
            ProptestConfig::with_cases(256),
            |(a in prop::collection::vec(any::<i64>(), 1..=512))| {
                prop_assert_eq!(last_min_index(&a), ref_last_min(&a));
            }
        }
    }

    // Property 3: when the minimum is unique, the answer is its single index.
    #[test]
    fn prop_unique_minimum() {
        let unique_min =
            prop::collection::vec(any::<i64>(), 1..=64)
                .prop_filter("unique minimum", |a| {
                    a.iter()
                        .filter(|&&x| x == *a.iter().min().unwrap())
                        .count()
                        == 1
                });
        proptest! {
            ProptestConfig::with_cases(256),
            |(a in unique_min)| {
                let min = *a.iter().min().unwrap();
                let expected = a.iter().position(|&x| x == min).unwrap();
                prop_assert_eq!(last_min_index(&a), expected);
            }
        }
    }

    // Property 4: with a small alphabet the minimum is heavily repeated; the
    // answer must always be the last position holding it. This is the
    // property that distinguishes "last minimum" from "first minimum".
    #[test]
    fn prop_repeated_minimum_small_alphabet() {
        proptest! {
            ProptestConfig::with_cases(512),
            |(a in prop::collection::vec((-4i64)..5, 1..=128))| {
                prop_assert_eq!(last_min_index(&a), ref_last_min(&a));
                let min = *a.iter().min().unwrap();
                prop_assert_eq!(a[last_min_index(&a)], min);
            }
        }
    }

    // Property 5: two-element and specific adversarial shapes.
    #[test]
    fn prop_pairs_and_shapes() {
        proptest! {
            ProptestConfig::with_cases(512),
            |(x in any::<i64>(), y in any::<i64>())| {
                let v = [x, y];
                prop_assert_eq!(last_min_index(&v), ref_last_min(&v));
            }
        }
    }
}

//! Returns whether a slice is strictly increasing.

/// Returns `true` exactly when every element of `a` is strictly smaller than
/// the next one (`a[i] < a[i + 1]` for every valid `i`).
///
/// Empty and one-element slices are strictly increasing.
pub fn strictly_increasing(a: &[i64]) -> bool {
    a.windows(2).all(|w| w[0] < w[1])
}

#[cfg(test)]
mod tests {
    use super::strictly_increasing;

    #[test]
    fn empty_slice_is_strictly_increasing() {
        assert!(strictly_increasing(&[]));
    }

    #[test]
    fn single_element_is_strictly_increasing() {
        assert!(strictly_increasing(&[42]));
        assert!(strictly_increasing(&[i64::MIN]));
        assert!(strictly_increasing(&[i64::MAX]));
    }

    #[test]
    fn strictly_increasing_slices() {
        assert!(strictly_increasing(&[1, 2, 3]));
        assert!(strictly_increasing(&[-5, -4, 0, 100]));
        assert!(strictly_increasing(&[i64::MIN, i64::MAX]));
    }

    #[test]
    fn non_increasing_slices() {
        // Equal adjacent elements break strict increase.
        assert!(!strictly_increasing(&[1, 1]));
        assert!(!strictly_increasing(&[1, 2, 2, 3]));
        assert!(!strictly_increasing(&[3, 3, 3]));
        // Decreasing pairs.
        assert!(!strictly_increasing(&[2, 1]));
        assert!(!strictly_increasing(&[1, 3, 2, 4]));
        assert!(!strictly_increasing(&[i64::MAX, i64::MIN]));
    }

    /// Independent reference implementation for property testing.
    fn reference(a: &[i64]) -> bool {
        for i in 0..a.len().saturating_sub(1) {
            if !(a[i] < a[i + 1]) {
                return false;
            }
        }
        true
    }

    proptest::proptest! {
        #[test]
        fn matches_reference(
            a in proptest::collection::vec(proptest::arbitrary::any::<i64>(), 0..32)
        ) {
            assert_eq!(strictly_increasing(&a), reference(&a));
        }

        #[test]
        fn random_sorted_slices_are_strictly_increasing(
            a in proptest::collection::vec(proptest::arbitrary::any::<i64>(), 0..32)
        ) {
            let mut sorted = a;
            sorted.sort();
            // Deduplicate to guarantee strict increase.
            sorted.dedup();
            assert!(strictly_increasing(&sorted));
        }
    }
}

/// Returns the smallest index `i` such that `a[i] >= t`,
/// or `a.len()` if every element is smaller than `t`.
///
/// `a` must be sorted in non-decreasing order.
/// Uses binary search.
pub fn lower_bound(a: &[i64], t: i64) -> usize {
    let mut lo = 0usize;
    let mut hi = a.len();
    while lo < hi {
        // Split point; cannot overflow since hi >= lo.
        let mid = lo + (hi - lo) / 2;
        if a[mid] >= t {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    lo
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn linear_lower_bound(a: &[i64], t: i64) -> usize {
        a.iter().position(|&x| x >= t).unwrap_or(a.len())
    }

    #[test]
    fn empty_slice() {
        assert_eq!(lower_bound(&[], 0), 0);
        assert_eq!(lower_bound(&[], i64::MIN), 0);
        assert_eq!(lower_bound(&[], i64::MAX), 0);
    }

    #[test]
    fn single_element() {
        assert_eq!(lower_bound(&[5], 5), 0);
        assert_eq!(lower_bound(&[5], 6), 1);
        assert_eq!(lower_bound(&[5], 4), 0);
        assert_eq!(lower_bound(&[i64::MIN], i64::MIN), 0);
        assert_eq!(lower_bound(&[i64::MAX], i64::MAX), 0);
        assert_eq!(lower_bound(&[i64::MAX], i64::MAX - 1), 0);
    }

    #[test]
    fn duplicates() {
        let a = [3, 3, 3, 3];
        assert_eq!(lower_bound(&a, 3), 0);
        assert_eq!(lower_bound(&a, 2), 0);
        assert_eq!(lower_bound(&a, 4), 4);
        let b = [1, 2, 2, 2, 5, 7];
        assert_eq!(lower_bound(&b, 2), 1);
        assert_eq!(lower_bound(&b, 5), 4);
        assert_eq!(lower_bound(&b, 6), 5);
        assert_eq!(lower_bound(&b, 8), 6);
        assert_eq!(lower_bound(&b, 0), 0);
    }

    #[test]
    fn extremes() {
        let a = [i64::MIN, i64::MIN, 0, i64::MAX, i64::MAX];
        assert_eq!(lower_bound(&a, i64::MIN), 0);
        assert_eq!(lower_bound(&a, i64::MAX), 3);
        assert_eq!(lower_bound(&a, i64::MAX + 0), 3);
        assert_eq!(lower_bound(&a, i64::MAX - 1), 3);
        assert_eq!(lower_bound(&a, i64::MIN + 1), 2);
        assert_eq!(lower_bound(&a, 1), 3);
    }

    #[test]
    fn strictly_sorted() {
        let a: Vec<i64> = (0..100).step_by(7).collect();
        for t in -3..=70 {
            assert_eq!(lower_bound(&a, t), linear_lower_bound(&a, t));
        }
    }

    proptest! {
        #[test]
        fn prop_matches_linear_scan(sorted in prop::collection::vec(any::<i64>(), 0..128), t in any::<i64>()) {
            let mut a = sorted;
            a.sort();
            prop_assert_eq!(lower_bound(&a, t), linear_lower_bound(&a, t));
        }

        #[test]
        fn prop_invariants(a in prop::collection::vec(any::<i64>(), 0..128), t in any::<i64>()) {
            let mut a = a;
            a.sort();
            let i = lower_bound(&a, t);
            // Index is in range.
            prop_assert!(i <= a.len());
            // Definition: everything before i is < t,
            // and at i (if it exists) a[i] >= t.
            prop_assert!(a[..i].iter().all(|&x| x < t));
            if i < a.len() {
                prop_assert!(a[i] >= t);
            }
        }
    }
}

//! Floor (toward negative infinity) division for `i64`.

/// Returns `a / b` rounded toward negative infinity, i.e. `floor(a / b)`.
///
/// Rust's `/` rounds toward zero, so the results differ exactly when
/// `a % b != 0` and `a` and `b` have different signs (the result is then
/// one less than the truncated quotient).
///
/// # Examples
/// ```
/// assert_eq!(solution::div_floor(7, 2), 3);
/// assert_eq!(solution::div_floor(-7, 2), -4);
/// assert_eq!(solution::div_floor(7, -2), -4);
/// assert_eq!(solution::div_floor(-7, -2), 3);
/// ```
///
/// # Domain
/// `b != 0`. The pair `(i64::MIN, -1)` is excluded from the intended
/// domain because its exact quotient (`2^63`) does not fit in `i64`; that
/// single input saturates to `i64::MAX` instead of panicking.
pub fn div_floor(a: i64, b: i64) -> i64 {
    // The only input pair for which the quotient does not fit in `i64`
    // (and for which `/` would overflow). Outside the stated domain;
    // saturate rather than panic.
    if a == i64::MIN && b == -1 {
        return i64::MAX;
    }

    let q = a / b; // truncates toward zero
    let r = a % b; // has the sign of `a`
    if r != 0 && (a < 0) != (b < 0) {
        // Truncated quotient lies strictly above the floor: step down.
        q - 1
    } else {
        q
    }
}

#[cfg(test)]
mod tests {
    use super::div_floor;

    #[test]
    fn task_examples() {
        assert_eq!(div_floor(7, 2), 3);
        assert_eq!(div_floor(-7, 2), -4);
        assert_eq!(div_floor(7, -2), -4);
        assert_eq!(div_floor(-7, -2), 3);
    }

    #[test]
    fn exact_quotients_and_small_values() {
        assert_eq!(div_floor(8, 2), 4);
        assert_eq!(div_floor(-8, 2), -4);
        assert_eq!(div_floor(8, -2), -4);
        assert_eq!(div_floor(-8, -2), 4);
        assert_eq!(div_floor(0, 5), 0);
        assert_eq!(div_floor(0, -5), 0);
        assert_eq!(div_floor(5, 1), 5);
        assert_eq!(div_floor(-5, 1), -5);
        assert_eq!(div_floor(5, -1), -5);
        assert_eq!(div_floor(-5, -1), 5);
        assert_eq!(div_floor(1, -2), -1);
        assert_eq!(div_floor(-1, 2), -1);
        assert_eq!(div_floor(1, 2), 0);
        assert_eq!(div_floor(-1, -2), 0);
    }

    #[test]
    fn extreme_values() {
        assert_eq!(div_floor(i64::MIN, 2), -4_611_686_018_427_387_904);
        assert_eq!(div_floor(i64::MIN, -2), 4_611_686_018_427_387_904);
        assert_eq!(div_floor(i64::MIN, 3), -3_074_457_345_618_258_603);
        assert_eq!(div_floor(i64::MIN, -3), 3_074_457_345_618_258_602);
        assert_eq!(div_floor(i64::MIN, i64::MIN), 1);
        // floor(-2^63 / (2^63 - 1)) = floor(-1.0000...1) = -2
        assert_eq!(div_floor(i64::MIN, i64::MAX), -2);
        // floor((2^63 - 1) / -2^63) = floor(-0.9999...9) = -1
        assert_eq!(div_floor(i64::MAX, i64::MIN), -1);
        assert_eq!(div_floor(i64::MAX, i64::MAX), 1);
        assert_eq!(div_floor(i64::MAX, 2), 4_611_686_018_427_387_903);
        assert_eq!(div_floor(i64::MAX, -2), -4_611_686_018_427_387_904);
        // floor((-2^63 + 1) / -2^63) = floor(0.9999...9) = 0
        assert_eq!(div_floor(-1, i64::MIN), 0);
        // floor(1 / -2^63) = floor(-0.0000...1) = -1
        assert_eq!(div_floor(1, i64::MIN), -1);
    }

    #[test]
    fn excluded_pair_does_not_panic() {
        // Not part of the domain; just make sure we saturate, not panic.
        assert_eq!(div_floor(i64::MIN, -1), i64::MAX);
    }
}

