use proptest::prelude::*;
use solution::div_floor;

// Excluded pair (not in the stated domain) must not panic.
#[test]
fn excluded_pair_is_safe() {
    let _ = div_floor(i64::MIN, -1);
}

proptest! {
    // Strongest check: compare against an exact i128 reference of the
    // floor of the real quotient, plus the remainder-range invariants.
    #[test]
    fn matches_exact_floor(a in any::<i64>(), b in any::<i64>()) {
        prop_assume!(b != 0 && !(a == i64::MIN && b == -1));
        let q = div_floor(a, b);
        let (ai, bi, qi) = (a as i128, b as i128, q as i128);
        let r = ai - qi * bi;
        // Remainder has the sign of the divisor (or is zero), magnitude < |b|.
        prop_assert!(r == 0 || (r > 0) == (b > 0));
        let ar = if r < 0 { -r } else { r };
        let ab = if b < 0 { -(b as i128) } else { b as i128 };
        prop_assert!(ar < ab);

        // Exact reference: truncate toward zero, adjust down when needed.
        let tq = ai / bi;
        let tr = ai % bi;
        let exact = if tr != 0 && (ai < 0) != (bi < 0) { tq - 1 } else { tq };
        prop_assert_eq!(qi, exact);
    }

    // For positive divisors, floor division equals Euclidean division.
    #[test]
    fn positive_divisor_eq_div_euclid(a in any::<i64>(), b in 1i64..=i64::MAX) {
        prop_assert_eq!(div_floor(a, b), a.div_euclid(b));
    }

    // For negative divisors, floor(a/b) = div_euclid(-a, -b) (a != MIN).
    #[test]
    fn negative_divisor_via_div_euclid(a in any::<i64>(), b in i64::MIN..=-1i64) {
        prop_assume!(a != i64::MIN);
        prop_assert_eq!(div_floor(a, b), (-a).div_euclid(-b));
    }

    // floor((a + b)/b) == floor(a/b) + 1, with small values so that
    // `a + b` and `q + 1` fit in i64.
    #[test]
    fn shift_by_divisor(a in -10_000_000_000i64..10_000_000_000i64,
                        b in -10_000_001i64..10_000_001i64) {
        prop_assume!(b != 0);
        prop_assert_eq!(div_floor(a + b, b), div_floor(a, b) + 1);
    }

    // Monotonicity in the dividend: nondecreasing for b > 0,
    // nonincreasing for b < 0.
    #[test]
    fn monotone_in_dividend(a in -10_000_000_000i64..10_000_000_000i64,
                            a2 in -10_000_000_000i64..10_000_000_000i64,
                            b in -10_000_001i64..10_000_001i64) {
        prop_assume!(b != 0 && a < a2);
        if b > 0 {
            prop_assert!(div_floor(a, b) <= div_floor(a2, b));
        } else {
            prop_assert!(div_floor(a, b) >= div_floor(a2, b));
        }
    }
}

