//! Floor-modulo helper.

/// Returns `a - b * floor(a / b)`, the remainder of floor division.
///
/// The result is either `0`, or has the same sign as `b`, and its absolute
/// value is strictly smaller than `|b|`.
///
/// # Panics
/// Panics (division by zero) if `b == 0`; the domain guarantees `b != 0`.
///
/// # Examples
/// ```
/// assert_eq!(solution::mod_floor(7, 3), 1);
/// assert_eq!(solution::mod_floor(-7, 3), 2);
/// assert_eq!(solution::mod_floor(7, -3), -2);
/// assert_eq!(solution::mod_floor(-7, -3), -1);
/// ```
pub fn mod_floor(a: i64, b: i64) -> i64 {
    debug_assert!(b != 0, "b must not be zero");
    // Every integer is divisible by 1 and -1, so the remainder is 0.
    // This also avoids `i64::MIN % -1`, which panics in debug builds.
    if b == 1 || b == -1 {
        return 0;
    }
    // Truncated-division remainder: sign of `a`, |r| < |b|, never overflows
    // for |b| >= 2.
    let r = a % b;
    if r == 0 || (r < 0) == (b < 0) {
        r
    } else {
        // r has the opposite sign of b and |r| < |b|, so r + b is nonzero,
        // has the sign of b, and |r + b| < |b|.
        // Overflow check: if b > 0 then 0 < r + b < b <= i64::MAX;
        // if b < 0 then b <= r + b < 0, and r + b > b >= i64::MIN
        // (in fact r + b >= i64::MIN + 1 here since r != 0).
        r + b
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn given_examples() {
        assert_eq!(mod_floor(7, 3), 1);
        assert_eq!(mod_floor(-7, 3), 2);
        assert_eq!(mod_floor(7, -3), -2);
        assert_eq!(mod_floor(-7, -3), -1);
    }

    #[test]
    fn small_values() {
        for a in -10..=10 {
            for b in (-10..=10).filter(|&x| x != 0) {
                let r = mod_floor(a, b);
                // sign property
                assert!(r == 0 || (r < 0) == (b < 0), "a={a} b={b} r={r}");
                // magnitude property
                assert!(
                    (r as i128).unsigned_abs() < (b as i128).unsigned_abs(),
                    "a={a} b={b} r={r}"
                );
                // a - r must be a multiple of b, and the quotient must be the
                // mathematical floor of a / b
                let a128 = a as i128;
                let b128 = b as i128;
                let r128 = r as i128;
                let q = (a128 - r128) / b128;
                assert_eq!(a128 - r128, q * b128, "a={a} b={b} r={r}");
                if b > 0 {
                    assert!(
                        q * b128 <= a128 && (q + 1) * b128 > a128,
                        "a={a} b={b} r={r}"
                    );
                } else {
                    assert!(
                        q * b128 >= a128 && (q + 1) * b128 < a128,
                        "a={a} b={b} r={r}"
                    );
                }
            }
        }
    }

    #[test]
    fn edge_cases() {
        // b = +/-1: every integer is divisible by it (i64::MIN % -1 would
        // panic in debug builds).
        assert_eq!(mod_floor(i64::MIN, -1), 0);
        assert_eq!(mod_floor(i64::MIN, 1), 0);
        assert_eq!(mod_floor(i64::MAX, -1), 0);
        assert_eq!(mod_floor(i64::MAX, 1), 0);
        assert_eq!(mod_floor(-1, 1), 0);
        assert_eq!(mod_floor(1, -1), 0);
        assert_eq!(mod_floor(0, 1), 0);
        assert_eq!(mod_floor(0, -1), 0);

        // Other extreme values of a and b (hand-verified).
        // 3074457345618258603 * 3 = 9223372036854775809
        assert_eq!(mod_floor(i64::MIN, 3), 1); // -9223372036854775808 + 9223372036854775809
        assert_eq!(mod_floor(i64::MIN, -3), -2);
        assert_eq!(mod_floor(i64::MIN, 2), 0);
        assert_eq!(mod_floor(i64::MIN, -2), 0);
        assert_eq!(mod_floor(i64::MAX, 3), 1); // 3074457345618258602 * 3 = 9223372036854775806
        assert_eq!(mod_floor(i64::MAX, -3), -2);
        // b = i64::MIN = -2^63
        assert_eq!(mod_floor(-1, i64::MIN), -1);
        assert_eq!(mod_floor(1, i64::MIN), -i64::MAX); // 1 - 2^63
        assert_eq!(mod_floor(i64::MAX, i64::MIN), -1); // (2^63 - 1) - 2^63
        assert_eq!(mod_floor(i64::MIN, i64::MIN), 0);

        // Small two-sided checks.
        assert_eq!(mod_floor(-1, 2), 1);
        assert_eq!(mod_floor(-2, 2), 0);
        assert_eq!(mod_floor(2, -2), 0);
        assert_eq!(mod_floor(1, -2), -1);
        assert_eq!(mod_floor(0, 5), 0);
        assert_eq!(mod_floor(0, -5), 0);
        assert_eq!(mod_floor(5, 2), 1);
        assert_eq!(mod_floor(-5, 2), 1);
        assert_eq!(mod_floor(5, -2), -1);
        assert_eq!(mod_floor(-5, -2), -1);
        assert_eq!(mod_floor(1, 7), 1);
        assert_eq!(mod_floor(-1, 7), 6);
        assert_eq!(mod_floor(1, -7), -6);
        assert_eq!(mod_floor(-1, -7), -1);
    }

    /// Independent reference computed in i128 (no overflow possible there).
    fn ref_mod_floor(a: i64, b: i64) -> i64 {
        let a = a as i128;
        let b = b as i128;
        let mut r = a % b;
        if r != 0 && (r < 0) != (b < 0) {
            r += b;
        }
        r as i64
    }

    proptest! {
        #[test]
        fn property(a in any::<i64>(), b in any::<i64>()) {
            prop_assume!(b != 0);
            let r = mod_floor(a, b);

            // 0 or the sign of b
            prop_assert!(r == 0 || (r < 0) == (b < 0));
            // |r| < |b|
            prop_assert!((r as i128).unsigned_abs() < (b as i128).unsigned_abs());

            let a128 = a as i128;
            let b128 = b as i128;
            let r128 = r as i128;

            // a - r is exactly divisible by b
            let diff = a128 - r128;
            prop_assert_eq!(diff % b128, 0);
            let q = diff / b128; // quotient = floor(a / b)

            // q must be the mathematical floor of a / b
            if b > 0 {
                prop_assert!(q * b128 <= a128);
                prop_assert!((q + 1) * b128 > a128);
            } else {
                prop_assert!(q * b128 >= a128);
                prop_assert!((q + 1) * b128 < a128);
            }

            // matches the i128 reference
            prop_assert_eq!(r, ref_mod_floor(a, b));
        }

        // Targeted stress around the extreme values, compared to the i128
        // reference.
        #[test]
        fn extremes(
            a in prop_oneof![
                Just(i64::MIN), Just(i64::MIN + 1), Just(i64::MAX),
                Just(i64::MAX - 1), Just(0), Just(1), Just(-1),
                any::<i64>()
            ],
            b in prop_oneof![
                Just(i64::MIN), Just(i64::MIN + 1), Just(i64::MAX),
                Just(i64::MAX - 1), Just(-2), Just(-1), Just(1), Just(2),
                any::<i64>()
            ]
        ) {
            prop_assume!(b != 0);
            prop_assert_eq!(mod_floor(a, b), ref_mod_floor(a, b));
        }

        // For positive b, the classic formula (a % b + b) % b is safe in i64
        // only for moderate values; check agreement for small magnitudes.
        #[test]
        fn matches_positive_b_formula(
            a in -1_000_000_000i64..=1_000_000_000,
            b in 1..=1_000_000_000i64
        ) {
            let expected = (a % b + b) % b;
            prop_assert_eq!(mod_floor(a, b), expected);
        }

        // Periodicity: mod_floor(a, b) depends only on a mod b.
        #[test]
        fn periodic(a in -10_000i64..=10_000, b in 2..=1_000i64) {
            for k in -3..=3 {
                prop_assert_eq!(mod_floor(a, b), mod_floor(a + k * b, b));
            }
        }
    }
}

//! Maximum subarray sum (Kadane's algorithm).

/// Returns the largest sum of a non-empty contiguous subarray of `a`.
///
/// `a` must be non-empty. Elements are `i64` in `[-1_000_000_000, 1_000_000_000]`
/// and `a.len() <= 1_000_000`, so the maximum possible sum is `1e15`,
/// which fits comfortably in `i64` — no overflow can occur for in-domain input.
pub fn max_subarray(a: &[i64]) -> i64 {
    // The slice is guaranteed non-empty by the input domain.
    let first = a[0];
    let mut best = first;
    let mut cur = first;
    for &x in &a[1..] {
        // Either extend the previous run, or start a new run at `x`.
        // Use `checked_add`-free plain arithmetic: in-domain values
        // (cur in [-1e15, 1e15], x in [-1e9, 1e9]) cannot overflow i64.
        cur = if cur > 0 { cur + x } else { x };
        if cur > best {
            best = cur;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::max_subarray;

    #[test]
    fn single_element_positive() {
