        // -2, 1, -3, 4, -1, 2, 1, -5, 4 -> best run is 4,-1,2,1 = 6
        assert_eq!(max_subarray(&[-2, 1, -3, 4, -1, 2, 1, -5, 4]), 6);
    }

    #[test]
    fn all_positive_is_whole_slice() {
        assert_eq!(max_subarray(&[1, 2, 3, 4]), 10);
    }

    #[test]
    fn negatives_around_positive_block() {
        assert_eq!(max_subarray(&[-100, 10, 20, -100]), 30);
    }

    #[test]
    fn best_at_end() {
        assert_eq!(max_subarray(&[-1, -2, -3, 5]), 5);
    }

    #[test]
    fn best_at_start() {
        assert_eq!(max_subarray(&[9, -1, -2, -3]), 9);
    }

    #[test]
    fn extremes_fit_in_i64() {
        // 1_000_000 * 1e9 = 1e15, within i64.
        let a: Vec<i64> = vec![1_000_000_000; 1_000_000];
        assert_eq!(max_subarray(&a), 1_000_000 * 1_000_000_000);

        let b: Vec<i64> = vec![-1_000_000_000; 1_000_000];
        assert_eq!(max_subarray(&b), -1_000_000_000);
    }

    #[test]
    fn alternating_extremes() {
        let a: Vec<i64> = (0..100_000)
            .map(|i| if i % 2 == 0 { 1_000_000_000 } else { -1_000_000_000 })
            .collect();
        // Best is a single element: 1e9
        assert_eq!(max_subarray(&a), 1_000_000_000);
    }

    use proptest::prelude::*;

    fn brute_force(a: &[i64]) -> i64 {
        let mut best = i64::MIN;
        for i in 0..a.len() {
            let mut s = 0i64;
            for j in i..a.len() {
                s += a[j];
                if s > best {
                    best = s;
                }
            }
        }
        best
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(256))]

        /// Random small arrays (including all-negative): agree with brute force.
        #[test]
        fn matches_brute_force_small(xs in proptest::collection::vec(-1_000_000_000i64..=1_000_000_000, 1..60)) {
            prop_assert_eq!(max_subarray(&xs), brute_force(&xs));
        }

        /// Small-magnitude random arrays.
        #[test]
        fn matches_brute_force_small_magnitude(xs in proptest::collection::vec(-50i64..=50, 1..80)) {
            prop_assert_eq!(max_subarray(&xs), brute_force(&xs));
        }

        /// Larger arrays with a planted positive block: sum must be computed exactly.
        #[test]
        fn large_planted_block(prefix in proptest::collection::vec(-1_000_000_000i64..=1_000_000_000, 0..200),
                              block in proptest::collection::vec(1i64..=1_000_000_000, 1..200),
                              suffix in proptest::collection::vec(-1_000_000_000i64..=1_000_000_000, 0..200)) {
            let mut a = prefix;
            a.extend(block.iter());
            a.extend(suffix.iter());
            let block_sum: i64 = block.iter().sum();
            // Brute force over 200-ish prefix/suffix around the block is expensive
            // globally, so verify: the answer is at least the block sum, and
            // equals the full-range brute force on a truncated copy (block sum
            // alone guarantees the optimum lies within block ± neighbors, but
            // to be safe, brute force the whole thing when it is small enough).
            if a.len() <= 60 {
                prop_assert_eq!(max_subarray(&a), brute_force(&a));
            } else {
                prop_assert!(max_subarray(&a) >= block_sum);
            }
        }
    }
}

//! Computes the second largest distinct value of a slice of `i64`.

/// Returns the second largest distinct value of `a`:
/// the largest value that is strictly smaller than the maximum of `a`.
///
/// If `a` has fewer than two distinct values (including when `a` is empty),
/// returns `i64::MIN`.
pub fn second_max(a: &[i64]) -> i64 {
    let mut max: Option<i64> = None;
    let mut second: Option<i64> = None;
    for &x in a {
        match max {
            None => max = Some(x),
            Some(m) => {
                if x > m {
                    // The old maximum becomes the second largest.
                    second = Some(m);
                    max = Some(x);
                } else if x < m {
                    // Strictly smaller than the maximum: track the largest such value.
                    if second.map_or(true, |s| x > s) {
                        second = Some(x);
                    }
                }
            }
        }
    }
    second.unwrap_or(i64::MIN)
}

#[cfg(test)]
