/// Rotate `a` to the right by `k` positions in place: the element at index `i`
/// moves to index `(i + k) mod a.len()`.
///
/// `k` may be larger than `a.len()`; an empty slice stays empty.
pub fn rotate_right(a: &mut [i64], k: usize) {
    let n = a.len();
    if n <= 1 {
        return;
    }
    let k = k % n;
    if k == 0 {
        return;
    }
    // Classic in-place reversal algorithm for a right rotation by `k`:
    // 1. reverse the whole slice,
    // 2. reverse the first `k` elements,
    // 3. reverse the remaining `n - k` elements.
    a.reverse();
    a[..k].reverse();
    a[k..].reverse();
}

#[cfg(test)]
mod tests {
    use super::rotate_right;

    #[test]
    fn empty_slice_stays_empty() {
        let mut a: [i64; 0] = [];
        rotate_right(&mut a, 0);
        rotate_right(&mut a, 7);
        rotate_right(&mut a, usize::MAX);
        assert!(a.is_empty());
    }

    #[test]
    fn single_element() {
        let mut a = [42];
        rotate_right(&mut a, 5);
        assert_eq!(a, [42]);
    }

    #[test]
    fn basic_rotations() {
        let mut a = [1, 2, 3, 4, 5];
        rotate_right(&mut a, 2);
        assert_eq!(a, [4, 5, 1, 2, 3]);

        let mut a = [1, 2, 3, 4, 5];
        rotate_right(&mut a, 1);
        assert_eq!(a, [5, 1, 2, 3, 4]);

        let mut a = [1, 2, 3, 4, 5];
        rotate_right(&mut a, 4);
        assert_eq!(a, [2, 3, 4, 5, 1]);
    }

    #[test]
    fn k_zero_and_multiples_of_len() {
        for k in [0usize, 5, 10, 15] {
            let mut a = [1, 2, 3, 4, 5];
            rotate_right(&mut a, k);
            assert_eq!(a, [1, 2, 3, 4, 5]);
        }
    }

    #[test]
    fn huge_k() {
        // usize::MAX = 2^64 - 1 is divisible by 3, so this is a no-op.
        let mut a = [1, 2, 3];
        rotate_right(&mut a, usize::MAX);
        assert_eq!(a, [1, 2, 3]);

        // 2^64 - 1 ≡ 1 (mod 7), so rotating a 7-element slice by usize::MAX
        // is a right rotation by 1.
        let mut b = [1, 2, 3, 4, 5, 6, 7];
        rotate_right(&mut b, usize::MAX);
        assert_eq!(b, [7, 1, 2, 3, 4, 5, 6]);
    }

    #[test]
    fn two_elements() {
        let mut a = [1, 2];
        rotate_right(&mut a, 1);
        assert_eq!(a, [2, 1]);
        rotate_right(&mut a, 1);
        assert_eq!(a, [1, 2]);
        rotate_right(&mut a, 3);
        assert_eq!(a, [2, 1]);
    }

    #[test]
    fn half_rotation() {
        let mut a = [1, 2, 3, 4];
        rotate_right(&mut a, 2);
        assert_eq!(a, [3, 4, 1, 2]);
    }

    #[test]
    fn inverse_property() {
        // Rotating right by k and then right by n - k is the identity.
        let original = [9, -3, 0, 7, 5, -8, 12];
        let n = original.len();
        for k in 0..n {
            let mut a = original;
            rotate_right(&mut a, k);
            rotate_right(&mut a, (n - k) % n);
            assert_eq!(a, original);
        }
    }

    #[test]
    fn permutation_preservation() {
        // Rotation must not change the multiset of values.
        let mut a = vec![5, -1, 0, 5, 5, -1, 3];
        let mut sorted_orig = a.clone();
        sorted_orig.sort_unstable();
        rotate_right(&mut a, 1000003);
        a.sort_unstable();
        assert_eq!(a, sorted_orig);
    }

    #[test]
    fn negative_values() {
        let mut a = [-5, -10, -3, -7];
        rotate_right(&mut a, 3);
        assert_eq!(a, [-10, -3, -7, -5]);
    }
}

