/// `a` is sorted in non-decreasing order.
///
/// In place, moves the distinct values of `a` to the front in increasing
/// order, sets every remaining position to `0`, and returns the number of
/// distinct values.
pub fn dedup_sorted(a: &mut [i64]) -> usize {
    let n = a.len();
    if n == 0 {
        return 0;
    }

    // Two-pointer dedup: because the slice is sorted, distinct values are
    // encountered in increasing order, so compacting consecutive runs
    // already places them at the front in the required order.
    let mut k = 1;
    for i in 1..n {
        if a[i] != a[i - 1] {
            if k != i {
                a[k] = a[i];
            }
            k += 1;
        }
    }

    for j in k..n {
        a[j] = 0;
    }
    k
}

#[cfg(test)]
mod tests {
    use super::dedup_sorted;
    use proptest::prelude::*;

    fn run(mut a: Vec<i64>) -> (usize, Vec<i64>) {
        let r = dedup_sorted(&mut a);
        (r, a)
    }

    fn expected(v: &[i64]) -> (usize, Vec<i64>) {
        // v is assumed sorted non-decreasingly.
        let mut distinct: Vec<i64> = Vec::new();
        for &x in v {
            match distinct.last() {
                Some(&last) if last == x => {}
                _ => distinct.push(x),
            }
        }
        let r = distinct.len();
        distinct.resize(v.len(), 0);
        (r, distinct)
    }

    #[test]
    fn empty() {
        let mut a = Vec::<i64>::new();
        assert_eq!(dedup_sorted(&mut a), 0);
        assert!(a.is_empty());
    }

    #[test]
    fn single() {
        assert_eq!(run(vec![42]), expected(&[42]));
        assert_eq!(run(vec![0]), expected(&[0]));
        assert_eq!(run(vec![i64::MIN]), expected(&[i64::MIN]));
        assert_eq!(run(vec![i64::MAX]), expected(&[i64::MAX]));
    }

    #[test]
    fn all_equal() {
        assert_eq!(run(vec![7, 7, 7, 7]), expected(&[7, 7, 7, 7]));
        assert_eq!(run(vec![0, 0, 0]), expected(&[0, 0, 0]));
        assert_eq!(run(vec![i64::MIN; 5]), expected(&[i64::MIN; 5]));
    }

    #[test]
    fn distinct() {
        assert_eq!(run(vec![1, 2, 3]), expected(&[1, 2, 3]));
        assert_eq!(
            run(vec![i64::MIN, 0, i64::MAX]),
            expected(&[i64::MIN, 0, i64::MAX])
        );
    }

    #[test]
    fn mixed() {
        assert_eq!(
            run(vec![-5, -5, -1, 0, 0, 0, 3, 9, 9]),
            expected(&[-5, -5, -1, 0, 0, 0, 3, 9, 9])
        );
        // 0 among distinct values; padding is also 0 — length disambiguates.
        assert_eq!(run(vec![0, 0, 1, 2]), expected(&[0, 0, 1, 2]));
        assert_eq!(
            run(vec![-2, -2, 0, 0, 0, 5, 5]),
            expected(&[-2, -2, 0, 0, 0, 5, 5])
        );
        // Minimal regression case from an earlier test bug.
        assert_eq!(run(vec![-1, 0]), expected(&[-1, 0]));
    }

    #[test]
    fn no_overflow_at_extremes() {
        // Adjacent extreme values must compare fine (no arithmetic on values).
        assert_eq!(
            run(vec![i64::MAX - 1, i64::MAX]),
            expected(&[i64::MAX - 1, i64::MAX])
        );
        assert_eq!(
            run(vec![i64::MIN, i64::MIN + 1]),
            expected(&[i64::MIN, i64::MIN + 1])
        );
    }

    #[test]
    fn length_preserved() {
        let mut a = vec![1, 1, 2, 3, 3, 3, 4];
        let r = dedup_sorted(&mut a);
        assert_eq!(a.len(), 7);
        assert_eq!(r, 4);
        assert_eq!(a, vec![1, 2, 3, 4, 0, 0, 0]);
    }

    proptest! {
        #[test]
        fn prop_sorted_i64(input in proptest::collection::vec(any::<i64>(), 0..=256)) {
            let mut sorted: Vec<i64> = input.clone();
            sorted.sort_unstable();
            let mut a = sorted.clone();
            let r = dedup_sorted(&mut a);
            let (er, ea) = expected(&sorted);
            assert_eq!(r, er);
            assert_eq!(a, ea);
        }

        #[test]
        fn prop_small_values(input in proptest::collection::vec(-10i64..=10, 0..=64)) {
            let mut sorted: Vec<i64> = input.clone();
            sorted.sort_unstable();
            let mut a = sorted.clone();
            let r = dedup_sorted(&mut a);
            let (er, ea) = expected(&sorted);
            assert_eq!(r, er);
            assert_eq!(a, ea);
            // Front section strictly increasing.
            for w in a[..r].windows(2) {
                assert!(w[0] < w[1]);
            }
            // Rest all zeros.
            assert!(a[r..].iter().all(|&x| x == 0));
        }
    }
}

/// In place, move every zero element of `a` to the end, keeping the
/// relative order of the non-zero elements.
pub fn move_zeros(a: &mut [i64]) {
    let mut write = 0;
    for read in 0..a.len() {
        if a[read] != 0 {
            a.swap(write, read);
            write += 1;
        }
    }
}

