//! Greatest common divisor for `i64` values.

/// Returns the greatest common divisor of `|a|` and `|b|`.
///
/// The result is never negative:
/// - `gcd(0, 0) == 0`
/// - `gcd(a, 0) == |a|`
/// - `gcd(a, b) == gcd(|a|, |b|)`
///
/// Inputs are expected to be `i64` values greater than `i64::MIN`,
/// so that their absolute values still fit in `i64`.
pub fn gcd(a: i64, b: i64) -> i64 {
    // Safe: inputs are greater than i64::MIN by the stated domain,
    // so the absolute values fit in i64.
    let mut a = a.abs();
    let mut b = b.abs();
    while b != 0 {
        let t = a % b;
        a = b;
        b = t;
    }
    a
}

